 3	final class TrieDemo {
 4	    private static final String[] WORDS = {"and", "ant", "do", "dad"};
 5	    private static final String[] SEARCH_KEYS = {"do", "gee", "bat"};
 6	    private static final String[] PREFIX_KEYS = {"ge", "ba", "do", "de"};
 7	
 8	    private TrieDemo() {
 9	    }
10	
11	    public static void main(String[] args) {
12	        Trie trie = buildTrie(WORDS);
13	
14	        printResults(SEARCH_KEYS, trie::contains);
15	        System.out.println();
16	        printResults(PREFIX_KEYS, trie::startsWith);
17	    }
18	
19	    private static Trie buildTrie(String[] words) {
20	        Trie trie = new Trie();
21	        for (String word : words) {
22	            trie.insert(word);
23	        }
24	        return trie;
25	    }
26	
27	    private static void printResults(String[] keys, Predicate<String> lookup) {
28	        for (String key : keys) {
29	            System.out.print(lookup.test(key) + " ");
30	        }
31	    }
32	}

