  3	public final class Trie {
  4	    private static final int ALPHABET_SIZE = 26;
  5	    private static final char FIRST_LETTER = 'a';
  6	    private static final char LAST_LETTER = 'z';
  7	
  8	    private final TrieNode root = new TrieNode();
  9	
 10	    /**
 11	     * Adds a lowercase word to the trie.
 12	     */
 13	    public void insert(String word) {
 14	        findOrCreateNode(word).markWord();
 15	    }
 16	
 17	    /**
 18	     * Returns true when the trie contains the complete lowercase word.
 19	     */
 20	    public boolean contains(String word) {
 21	        TrieNode node = findNode(word);
 22	        return node != null && node.isWord();
 23	    }
 24	
 25	    /**
 26	     * Compatibility alias for {@link #contains(String)}.
 27	     */
 28	    public boolean search(String word) {
 29	        return contains(word);
 30	    }
 31	
 32	    /**
 33	     * Returns true when the trie contains the lowercase prefix.
 34	     */
 35	    public boolean startsWith(String prefix) {
 36	        return findNode(prefix) != null;
 37	    }
 38	
 39	    /**
 40	     * Compatibility alias for {@link #startsWith(String)}.
 41	     */
 42	    public boolean isPrefix(String prefix) {
 43	        return startsWith(prefix);
 44	    }
 45	
 46	    private TrieNode findNode(String value) {
 47	        return walk(value, MissingNodePolicy.STOP);
 48	    }
 49	
 50	    private TrieNode findOrCreateNode(String value) {
 51	        return walk(value, MissingNodePolicy.CREATE);
 52	    }
 53	
 54	    private TrieNode walk(String value, MissingNodePolicy missingNodePolicy) {
 55	        Objects.requireNonNull(value, "value must not be null");
 56	        TrieNode current = root;
 57	
 58	        for (int position = 0; position < value.length(); position++) {
 59	            int index = toIndex(value.charAt(position), value);
 60	            current = missingNodePolicy.next(current, index);
 61	            if (current == null) {
 62	                return null;
 63	            }
 64	        }
 65	
 66	        return current;
 67	    }
 68	
 69	    private static int toIndex(char letter, String value) {
 70	        if (letter < FIRST_LETTER || letter > LAST_LETTER) {
 71	            throw new IllegalArgumentException(
 72	                "Trie values may only contain lowercase letters a-z: " + value);
 73	        }
 74	
 75	        return letter - FIRST_LETTER;
 76	    }
 77	
 78	    private enum MissingNodePolicy {
 79	        CREATE {
 80	            @Override
 81	            TrieNode next(TrieNode node, int index) {
 82	                return node.getOrCreateChild(index);
 83	            }
 84	        },
 85	        STOP {
 86	            @Override
 87	            TrieNode next(TrieNode node, int index) {
 88	                return node.getChild(index);
 89	            }
 90	        };
 91	
 92	        abstract TrieNode next(TrieNode node, int index);
 93	    }
 94	
 95	    private static final class TrieNode {
 96	        private final TrieNode[] children = new TrieNode[ALPHABET_SIZE];
 97	        private boolean isWord;
 98	
 99	        private TrieNode getChild(int index) {
100	            return children[index];
101	        }
102	
103	        private TrieNode getOrCreateChild(int index) {
104	            if (children[index] == null) {
105	                children[index] = new TrieNode();
106	            }
107	
108	            return children[index];
109	        }
110	
111	        private boolean isWord() {
112	            return isWord;
113	        }
114	
115	        private void markWord() {
116	            isWord = true;
117	        }
118	    }
119	}

 1	final class TrieTest {
 2	    private TrieTest() {
 3	    }
 4	
 5	    public static void main(String[] args) {
 6	        containsCompleteWords();
 7	        detectsPrefixes();
 8	        rejectsUnsupportedInput();
 9	    }
10	
11	    private static void containsCompleteWords() {
12	        Trie trie = sampleTrie();
13	
14	        assertTrue(trie.contains("do"), "contains finds inserted words");
15	        assertTrue(trie.search("and"), "search remains a contains alias");
16	        assertFalse(trie.contains("gee"), "contains rejects missing words");
17	        assertFalse(trie.contains("an"), "contains requires a complete word");
18	    }
19	
20	    private static void detectsPrefixes() {
21	        Trie trie = sampleTrie();
22	
23	        assertTrue(trie.startsWith("an"), "startsWith finds inserted prefixes");
24	        assertTrue(trie.isPrefix("do"), "isPrefix remains a startsWith alias");
25	        assertFalse(trie.startsWith("de"), "startsWith rejects missing prefixes");
26	    }
27	
28	    private static void rejectsUnsupportedInput() {
29	        Trie trie = new Trie();
30	
31	        assertThrows(
32	            IllegalArgumentException.class,
33	            () -> trie.insert("Dad"),
34	            "insert rejects uppercase letters");
35	        assertThrows(
36	            NullPointerException.class,
37	            () -> trie.contains(null),
38	            "contains rejects null words");
39	    }
40	
41	    private static Trie sampleTrie() {
42	        Trie trie = new Trie();
43	        trie.insert("and");
44	        trie.insert("ant");
45	        trie.insert("do");
46	        trie.insert("dad");
47	        return trie;
48	    }
49	
50	    private static void assertTrue(boolean condition, String message) {
51	        if (!condition) {
52	            throw new AssertionError(message);
53	        }
54	    }
55	
56	    private static void assertFalse(boolean condition, String message) {
57	        assertTrue(!condition, message);
58	    }
59	
60	    private static void assertThrows(
61	        Class<? extends Throwable> expectedType,
62	        ThrowingRunnable action,
63	        String message) {
64	
65	        try {
66	            action.run();
67	        } catch (Throwable error) {
68	            if (expectedType.isInstance(error)) {
69	                return;
70	            }
71	            throw new AssertionError(message + ": expected " + expectedType.getSimpleName()
72	                + " but got " + error.getClass().getSimpleName(), error);
73	        }
74	
75	        throw new AssertionError(message + ": expected " + expectedType.getSimpleName());
76	    }
77	
78	    @FunctionalInterface
79	    private interface ThrowingRunnable {
80	        void run();
81	    }
82	}

